CREATE TABLE IF NOT EXISTS automation_definitions(automation_id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,trigger_json TEXT NOT NULL,action TEXT NOT NULL,approval_required INTEGER NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS automation_executions(execution_id TEXT PRIMARY KEY,automation_id TEXT NOT NULL,request_id TEXT NOT NULL,outcome TEXT NOT NULL,started_at TEXT NOT NULL,completed_at TEXT,side_effects_json TEXT NOT NULL,evidence_refs_json TEXT NOT NULL);